// Generates app/lib/features/sync/data/db_contract.g.dart from
// supabase/types/database.ts (itself generated by `supabase gen types` in CI).
// Run from the repo root: `dart tool/gen_db_contract.dart` (or `make db-types`).
// Plain dart:io on purpose: no package resolution, runs anywhere Dart runs.
import 'dart:io';

const _input = 'supabase/types/database.ts';
const _output = 'app/lib/features/sync/data/db_contract.g.dart';

void main() {
  final lines = File(_input).readAsLinesSync();
  final tables = _parseTables(lines);
  if (tables.isEmpty) {
    stderr.writeln('$_input: no tables found');
    exit(1);
  }
  File(_output)
    ..createSync(recursive: true)
    ..writeAsStringSync(_render(tables));
  // `make fmt-check` covers generated files too, so emit canonical formatting.
  final fmt = Process.runSync(Platform.resolvedExecutable, [
    'format',
    _output,
  ]);
  if (fmt.exitCode != 0) {
    stderr.write(fmt.stderr);
    exit(fmt.exitCode);
  }
}

/// table -> column -> (type, nullable), in file order.
typedef _Tables = Map<String, Map<String, ({String type, bool nullable})>>;

_Tables _parseTables(List<String> lines) {
  final tables = _Tables();
  final section = RegExp(r'^    (\w+): \{$');
  final tableStart = RegExp(r'^      (\w+): \{$');
  final column = RegExp(r'^\s+(\w+)(\??): (.+)$');
  var inTables = false;
  for (var i = 0; i < lines.length; i++) {
    final s = section.firstMatch(lines[i]);
    if (s != null) inTables = s.group(1) == 'Tables';
    final t = tableStart.firstMatch(lines[i]);
    if (!inTables || t == null) continue;
    if (i + 1 >= lines.length || lines[i + 1].trim() != 'Row: {') continue;
    final columns = <String, ({String type, bool nullable})>{};
    for (var j = i + 2; lines[j].trim() != '}'; j++) {
      final c = column.firstMatch(lines[j]);
      if (c == null) throw FormatException('Unparsable line: ${lines[j]}');
      var type = c.group(3)!;
      final nullable = type.endsWith(' | null');
      if (nullable) type = type.substring(0, type.length - ' | null'.length);
      columns[c.group(1)!] = (type: _mapType(type), nullable: nullable);
    }
    tables[t.group(1)!] = columns;
  }
  return tables;
}

String _mapType(String ts) => switch (ts) {
  'string' => 'string',
  'number' => 'number',
  'boolean' => 'boolean',
  'Json' => 'json',
  _ => throw FormatException('Unmapped TypeScript type: $ts'),
};

String _camel(String snake) {
  final parts = snake.split('_');
  return parts.first +
      parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
}

String _pascal(String snake) {
  final c = _camel(snake);
  return c[0].toUpperCase() + c.substring(1);
}

String _render(_Tables tables) {
  final b = StringBuffer()
    ..writeln('// GENERATED by tool/gen_db_contract.dart from $_input.')
    ..writeln('// Do not edit; run `make db-types` (CI fails on a stale file).')
    ..writeln()
    ..writeln(
      '/// Coarse server column type as seen in the generated TS types.',
    )
    ..writeln('/// uuid, text, timestamptz and bytea are all `string`; every')
    ..writeln('/// integer width is `number`; jsonb is `json`.')
    ..writeln('enum DbColumnType { string, number, boolean, json }')
    ..writeln()
    ..writeln('class DbColumn {')
    ..writeln('  const DbColumn(this.type, {required this.nullable});')
    ..writeln('  final DbColumnType type;')
    ..writeln('  final bool nullable;')
    ..writeln('}')
    ..writeln()
    ..writeln('/// Table names of the server schema (`public`).')
    ..writeln('abstract final class DbTables {');
  for (final t in tables.keys) {
    b.writeln("  static const ${_camel(t)} = '$t';");
  }
  b
    ..writeln('}')
    ..writeln();
  for (final e in tables.entries) {
    b
      ..writeln('/// Column names of `${e.key}`.')
      ..writeln('abstract final class Db${_pascal(e.key)}Cols {');
    for (final c in e.value.keys) {
      b.writeln("  static const ${_camel(c)} = '$c';");
    }
    b
      ..writeln('}')
      ..writeln();
  }
  b
    ..writeln('/// Server schema: table -> column -> type.')
    ..writeln('const dbContract = <String, Map<String, DbColumn>>{');
  for (final e in tables.entries) {
    b.writeln("  '${e.key}': {");
    for (final c in e.value.entries) {
      b.writeln(
        "    '${c.key}': DbColumn(DbColumnType.${c.value.type}, "
        'nullable: ${c.value.nullable}),',
      );
    }
    b.writeln('  },');
  }
  b.writeln('};');
  return b.toString();
}
